//! Addresses generated by the wallet's accounts (the `addresses` table of
//! zcash_client_sqlite 0.23, `wallet/db.rs`).
//!
//! Received notes and transparent outputs refer to the address row they were received
//! at; those references are what `v_address_uses` / `v_address_first_use` are built from,
//! which in turn drive transparent gap-limit address generation
//! (`AddressStore::find_gap_start`). The upsert rules follow `upsert_address` (`wallet.rs`)
//! and `store_address_range` (`wallet/transparent.rs`).

use std::collections::BTreeMap;

use ::transparent::address::TransparentAddress;
use zcash_keys::address::{Address, UnifiedAddress};
use zcash_protocol::consensus::BlockHeight;
use zip32::DiversifierIndex;

#[cfg(feature = "transparent-inputs")]
use ::transparent::keys::{NonHardenedChildIndex, TransparentKeyScope};

use crate::{AccountId, error::Error};

/// The key scope an address was derived at (sqlite `KeyScope`: 0 external, 1 internal,
/// 2 ephemeral, -1 foreign/imported).
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub(crate) enum KeyScope {
    External,
    Internal,
    Ephemeral,
    /// A standalone address imported without derivation information.
    Foreign,
}

impl KeyScope {
    #[cfg(feature = "transparent-inputs")]
    pub(crate) fn as_transparent(self) -> Option<TransparentKeyScope> {
        match self {
            KeyScope::External => Some(TransparentKeyScope::EXTERNAL),
            KeyScope::Internal => Some(TransparentKeyScope::INTERNAL),
            KeyScope::Ephemeral => Some(TransparentKeyScope::EPHEMERAL),
            KeyScope::Foreign => None,
        }
    }

    #[cfg(feature = "transparent-inputs")]
    pub(crate) fn from_transparent(scope: TransparentKeyScope) -> Result<Self, Error> {
        if scope == TransparentKeyScope::EXTERNAL {
            Ok(KeyScope::External)
        } else if scope == TransparentKeyScope::INTERNAL {
            Ok(KeyScope::Internal)
        } else if scope == TransparentKeyScope::EPHEMERAL {
            Ok(KeyScope::Ephemeral)
        } else {
            Err(Error::Other(
                "unsupported transparent key scope (only external, internal and ephemeral)"
                    .into(),
            ))
        }
    }
}

/// The wallet-internal identifier of an address row.
pub(crate) type AddressId = u64;

/// An address row.
#[derive(Debug, Clone, PartialEq)]
pub(crate) struct AddressRecord {
    pub(crate) account_id: AccountId,
    pub(crate) key_scope: KeyScope,
    /// The diversifier index (equal to the transparent child index for transparent
    /// derivations); `None` only for foreign (imported) addresses.
    pub(crate) diversifier_index: Option<DiversifierIndex>,
    /// The address itself: a Unified Address for external-scope rows, the transparent
    /// address for internal and ephemeral rows.
    pub(crate) address: Address,
    /// The transparent child index, set when the row has a transparent receiver derived
    /// at a non-hardened index.
    #[cfg(feature = "transparent-inputs")]
    pub(crate) transparent_child_index: Option<NonHardenedChildIndex>,
    /// The transparent receiver of the address (the address itself for transparent rows).
    pub(crate) transparent_receiver: Option<TransparentAddress>,
    /// When the address was first exposed (handed out, reserved, or seen on chain).
    pub(crate) exposed_at_height: Option<BlockHeight>,
    /// Unix time at which a client should next check the transparent receiver for UTXOs.
    pub(crate) next_check_time: Option<u64>,
}

/// The big-endian encoding of a diversifier index, so that keys sort by index.
fn di_be(di: &DiversifierIndex) -> [u8; 11] {
    let mut b = *di.as_bytes();
    b.reverse();
    b
}

#[derive(Debug, Clone, Default, PartialEq)]
pub(crate) struct AddressTable {
    next_id: AddressId,
    rows: BTreeMap<AddressId, AddressRecord>,
    /// UNIQUE (account_id, key_scope, diversifier_index_be).
    by_key: BTreeMap<(AccountId, KeyScope, [u8; 11]), AddressId>,
    /// UNIQUE (cached_transparent_receiver_address).
    by_transparent: BTreeMap<TransparentAddress, AddressId>,
}

impl AddressTable {
    pub(crate) fn new() -> Self {
        Self::default()
    }

    pub(crate) fn get(&self, id: AddressId) -> Option<&AddressRecord> {
        self.rows.get(&id)
    }

    pub(crate) fn iter(&self) -> impl Iterator<Item = (AddressId, &AddressRecord)> {
        self.rows.iter().map(|(id, r)| (*id, r))
    }

    pub(crate) fn for_account(
        &self,
        account: AccountId,
    ) -> impl Iterator<Item = (AddressId, &AddressRecord)> {
        self.rows
            .iter()
            .filter(move |(_, r)| r.account_id == account)
            .map(|(id, r)| (*id, r))
    }

    pub(crate) fn find(
        &self,
        account: AccountId,
        key_scope: KeyScope,
        di: &DiversifierIndex,
    ) -> Option<AddressId> {
        self.by_key.get(&(account, key_scope, di_be(di))).copied()
    }

    /// The row whose transparent receiver is `taddr`.
    pub(crate) fn find_by_transparent_receiver(
        &self,
        taddr: &TransparentAddress,
    ) -> Option<(AddressId, &AddressRecord)> {
        self.by_transparent
            .get(taddr)
            .and_then(|id| self.rows.get(id).map(|r| (*id, r)))
    }

    fn insert(&mut self, record: AddressRecord) -> Result<AddressId, Error> {
        if let Some(t) = &record.transparent_receiver {
            if self.by_transparent.contains_key(t) {
                return Err(Error::CorruptedData(
                    "transparent receiver already belongs to another address row".into(),
                ));
            }
        }
        let id = self.next_id;
        self.next_id = self
            .next_id
            .checked_add(1)
            .ok_or_else(|| Error::Other("address id space exhausted".into()))?;
        if let Some(di) = &record.diversifier_index {
            self.by_key
                .insert((record.account_id, record.key_scope, di_be(di)), id);
        }
        if let Some(t) = record.transparent_receiver {
            self.by_transparent.insert(t, id);
        }
        self.rows.insert(id, record);
        Ok(id)
    }

    /// `upsert_address`: records the external-scope Unified Address at `di` for `account`.
    ///
    /// On conflict, the exposure height becomes the lesser of the two; with
    /// `force_update_address`, an address that was never exposed is replaced, and one that
    /// was exposed as a different address is an error (diversifier index reuse).
    pub(crate) fn upsert_unified(
        &mut self,
        account: AccountId,
        di: DiversifierIndex,
        ua: &UnifiedAddress,
        exposed_at_height: Option<BlockHeight>,
        force_update_address: bool,
    ) -> Result<AddressId, Error> {
        let new_address = Address::Unified(Box::new(ua.clone()));
        if let Some(id) = self.find(account, KeyScope::External, &di) {
            let row = self
                .rows
                .get_mut(&id)
                .ok_or_else(|| Error::CorruptedData("address index out of sync".into()))?;
            if force_update_address {
                if row.exposed_at_height.is_some() && row.address != new_address {
                    return Err(Error::Other(format!(
                        "diversifier index {di:?} was already exposed as a different address"
                    )));
                }
                if row.exposed_at_height.is_none() {
                    row.address = new_address;
                }
            }
            row.exposed_at_height = match (row.exposed_at_height, exposed_at_height) {
                (Some(a), Some(b)) => Some(a.min(b)),
                (a, b) => a.or(b),
            };
            return Ok(id);
        }

        #[cfg(feature = "transparent-inputs")]
        let (transparent_child_index, transparent_receiver) = {
            let idx = NonHardenedChildIndex::try_from(di).ok();
            match (idx, ua.transparent()) {
                (Some(idx), Some(t)) => (Some(idx), Some(*t)),
                (_, None) => (None, None),
                (None, Some(_)) => {
                    return Err(Error::CorruptedData(
                        "a transparent receiver at a hardened index cannot be derived".into(),
                    ));
                }
            }
        };
        #[cfg(not(feature = "transparent-inputs"))]
        let transparent_receiver = None;

        self.insert(AddressRecord {
            account_id: account,
            key_scope: KeyScope::External,
            diversifier_index: Some(di),
            address: new_address,
            #[cfg(feature = "transparent-inputs")]
            transparent_child_index,
            transparent_receiver,
            exposed_at_height,
            next_check_time: None,
        })
    }

    /// `store_address_range`: records derived addresses at the given scope; rows that
    /// already exist are left unchanged (`ON CONFLICT DO NOTHING`).
    #[cfg(feature = "transparent-inputs")]
    pub(crate) fn store_range(
        &mut self,
        account: AccountId,
        key_scope: KeyScope,
        list: Vec<(Address, TransparentAddress, NonHardenedChildIndex)>,
    ) -> Result<(), Error> {
        for (address, taddr, child_index) in list {
            let di = DiversifierIndex::from(child_index);
            if self.find(account, key_scope, &di).is_some() {
                continue;
            }
            if let Some((_, existing)) = self.find_by_transparent_receiver(&taddr) {
                if existing.key_scope == KeyScope::Foreign {
                    // Importing standalone addresses is not supported by this backend
                    // (transparent-key-import is off), so a foreign row cannot exist.
                    return Err(Error::Other(
                        "upgrading an imported transparent address is not supported".into(),
                    ));
                }
                return Err(Error::CorruptedData(
                    "derived transparent address already recorded at another index".into(),
                ));
            }
            self.insert(AddressRecord {
                account_id: account,
                key_scope,
                diversifier_index: Some(di),
                address,
                transparent_child_index: Some(child_index),
                transparent_receiver: Some(taddr),
                exposed_at_height: None,
                next_check_time: None,
            })?;
        }
        Ok(())
    }

    /// Lowers the exposure height of the address to `height` (or sets it).
    pub(crate) fn mark_exposed(&mut self, id: AddressId, height: BlockHeight) {
        if let Some(row) = self.rows.get_mut(&id) {
            row.exposed_at_height = Some(row.exposed_at_height.map_or(height, |h| h.min(height)));
        }
    }

    /// The id the next inserted row receives.
    pub(crate) fn next_id(&self) -> AddressId {
        self.next_id
    }

    /// Rebuilds the table from stored rows (deserialization), checking its unique indices.
    pub(crate) fn from_parts(
        next_id: AddressId,
        rows: Vec<(AddressId, AddressRecord)>,
    ) -> Result<Self, Error> {
        let mut table = Self {
            next_id,
            ..Self::default()
        };
        for (id, record) in rows {
            if id >= next_id {
                return Err(Error::CorruptedData("address row id out of range".into()));
            }
            if let Some(di) = &record.diversifier_index {
                if table
                    .by_key
                    .insert((record.account_id, record.key_scope, di_be(di)), id)
                    .is_some()
                {
                    return Err(Error::CorruptedData("duplicate address row".into()));
                }
            }
            if let Some(t) = record.transparent_receiver {
                if table.by_transparent.insert(t, id).is_some() {
                    return Err(Error::CorruptedData(
                        "two address rows share a transparent receiver".into(),
                    ));
                }
            }
            if table.rows.insert(id, record).is_some() {
                return Err(Error::CorruptedData("duplicate address row id".into()));
            }
        }
        Ok(table)
    }

    /// `ON DELETE CASCADE` from `accounts`.
    pub(crate) fn remove_account(&mut self, account: AccountId) {
        let ids: Vec<AddressId> = self.for_account(account).map(|(id, _)| id).collect();
        for id in ids {
            if let Some(row) = self.rows.remove(&id) {
                if let Some(di) = &row.diversifier_index {
                    self.by_key.remove(&(row.account_id, row.key_scope, di_be(di)));
                }
                if let Some(t) = &row.transparent_receiver {
                    self.by_transparent.remove(t);
                }
            }
        }
    }
}
